include!("helpers.rs");
use std::{borrow::Cow,path::{Path,PathBuf},os::unix::fs::PermissionsExt};
use vlajmaji_store::{CollectionCatalogue as Cat,CollectionInput as Input,CollectionRequest as Request,CollectionSelection as Selection,CollectionErrorCategory as Category};
fn req<'a>(id:PackId,s:&'a SealedRelease,allow:bool)->Request<'a>{Request::new(vec![Input::SealedBytes{pack_id:id,release:Cow::Borrowed(&s.release),seal:Cow::Borrowed(&s.seal)}],Selection::Packs(vec![id]),allow).unwrap()}
fn state(root:&Path)->(u64,String,String){let cat=Cat::open(root).unwrap();let g=cat.generation().unwrap().unwrap();(cat.list().unwrap().local_revision,g.generation_id,sha(&std::fs::read(g.store_path.join("dictionary.sqlite3")).unwrap()))}
struct Restore(PathBuf);impl Drop for Restore{fn drop(&mut self){std::fs::set_permissions(&self.0,std::fs::Permissions::from_mode(0o700)).unwrap()}}
fn main(){let base=PathBuf::from(std::env::args_os().nth(1).unwrap());std::fs::create_dir(&base).unwrap();let m=models();let llg=seal_release(PackId::Llg,PackPayloadKind::Synthetic,&m[1]).unwrap();let jb=seal_release(PackId::LensiskuJbotci,PackPayloadKind::Synthetic,&m[0]).unwrap();
 let denied=base.join("no-opt-in");let e=Cat::install(&denied,req(PackId::Llg,&llg,false)).unwrap_err();assert_eq!(e.category(),Category::InvalidRequest);assert!(!denied.exists());let valid=Cat::install(&denied,req(PackId::Llg,&llg,true)).unwrap();assert_eq!(valid.local_revision,1);
 let before=state(&denied);let mut broken:serde_json::Value=serde_json::from_slice(&jb.release).unwrap();broken["metadata"]["assertions"][0]["entry"]=serde_json::json!("missing-entry-graph-control");let release=serde_json::to_vec(&broken).unwrap();let mut seal=PackSeal::from_json_bytes(&jb.seal).unwrap();seal.release_sha256=sha(&release);seal.release_bytes=release.len() as u64;let bad=SealedRelease{release,seal:serde_json::to_vec(&seal).unwrap()};let e=Cat::install(&denied,req(PackId::LensiskuJbotci,&bad,true)).unwrap_err();assert_eq!(e.category(),Category::InputInvalid);let mut cause:&(dyn std::error::Error+'static)=&e;let mut pack=false;let mut text=Vec::new();loop{pack|=cause.downcast_ref::<PackError>().is_some();text.push(cause.to_string());match cause.source(){Some(c)=>cause=c,None=>break}}assert!(pack);assert!(text.join(" ").contains("missing-entry-graph-control"));assert_eq!(state(&denied),before);let valid=Cat::install(&denied,req(PackId::LensiskuJbotci,&jb,true)).unwrap();assert_eq!(valid.local_revision,2);
 let root=base.join("write-fault");Cat::install(&root,req(PackId::Llg,&llg,true)).unwrap();let before=state(&root);let generations=root.join("generations");std::fs::set_permissions(&generations,std::fs::Permissions::from_mode(0o500)).unwrap();let restore=Restore(generations.clone());
 let probe=generations.join("direct-io-probe");let direct=std::fs::create_dir(&probe).unwrap_err();assert_eq!(direct.kind(),std::io::ErrorKind::PermissionDenied);assert!(!probe.exists());let e=Cat::install(&root,req(PackId::LensiskuJbotci,&jb,true)).unwrap_err();assert_eq!(e.category(),Category::ArtifactIo);let report=e.report("install");assert_eq!(report.activation.as_deref(),Some("not_activated"));assert_eq!(report.prior_local_revision,Some(1));assert_eq!(report.inputs.len(),1);assert_eq!(report.inputs[0].release_sha256.as_deref(),Some(sha(&jb.release).as_str()));let mut c:&(dyn std::error::Error+'static)=&e;let mut io=false;loop{if let Some(err)=c.downcast_ref::<std::io::Error>(){assert_eq!(err.kind(),direct.kind());assert_eq!(err.raw_os_error(),direct.raw_os_error());io=true;}match c.source(){Some(next)=>c=next,None=>break}}assert!(io);assert_eq!(state(&root),before);drop(restore);let valid=Cat::install(&root,req(PackId::LensiskuJbotci,&jb,true)).unwrap();assert_eq!(valid.local_revision,2);
 println!("{}",serde_json::json!({"ok":true,"scope":"tiny explicit installer prerequisite complements; no Full inputs","predicates":["Synthetic no-opt-in rejected without creating root","same Synthetic bytes with opt-in install","correctly repinned invalid assertion graph rejected with typed PackError and unchanged prior generation","same valid JB installs afterward","real stage allocation EACCES equals direct IO with known dispositions and unchanged prior generation","same install succeeds after restoring owned directory permissions"],"passed":6,"invalid_model_causes":text,"write_failure_report":report}));}
